sys.path.insert(0,str(Path(unreal.Paths.project_dir())/'MigrationStaging'))
from weapon_extension_helpers import *
from editor_toolset.toolsets.blueprint import _BlueprintCache
bp=asset('Interaction/BP_SurvivorInteractionCharacter')
fn(bp,'GetActiveFirearmID',[],[('ID','name')])
write(bp,'GetActiveFirearmID','''(fn GetActiveFirearmID ()
 (if (== (Variables|Default|GetPublicActiveSlot) 0) (return (Variables|Default|GetPublicPrimary)))
 (if (== (Variables|Default|GetPublicActiveSlot) 1) (return (Variables|Default|GetPublicSecondary)))
 (if (== (Variables|Default|GetPublicActiveSlot) 2) (return (Variables|Default|GetPublicSidearm))) (return "None"))''')
fn(bp,'GetActiveWeaponVisual',[],[('Visual',unreal.StaticMeshComponent.static_class())])
write(bp,'GetActiveWeaponVisual','''(fn GetActiveWeaponVisual ()
 (if (== (Variables|Default|GetPublicActiveSlot) 0) (return (Variables|Default|GetPrimaryVisual)))
 (if (== (Variables|Default|GetPublicActiveSlot) 1) (return (Variables|Default|GetSecondaryVisual)))
 (return (Variables|Default|GetSidearmVisual)))''')
for n,t,rep,array in [('ShotgunPelletCount','int',False,False),('ShotgunSpreadRadiusAt10m','float',False,False),('ShotgunPelletDamage','float',False,False),('RevolverDamage','float',False,False),('ShotgunRange','float',False,False),('ShotgunFullDamageRange','float',False,False),('ShotStart','Vector',False,False),('ShotDirection','Vector',False,False),('PelletEnd','Vector',False,False),('PublicShotEnds','Vector',True,True),('PublicShotHits','bool',True,True),('PublicShotStart','Vector',True,False),('PublicShotWeapon','name',True,False)]:var(bp,n,t,rep,array)
fn(bp,'TraceFirearmPellet',[('End','Vector'),('Damage','float')])
B.compile_blueprint(bp,warnings_as_errors=True);_BlueprintCache.invalidate(bp)
write(bp,'TraceFirearmPellet','''(fn TraceFirearmPellet (End Damage)
 (bind (Hit DidHit) (Collision|LineTraceByChannel :Start (Variables|Default|GetShotStart) :End End :TraceChannel "TraceTypeQuery1" :ActorsToIgnore (Variables|Default|GetShotIgnoreActors)))
 (bind (Blocking Initial Time Distance Location ImpactPoint Normal ImpactNormal PhysMat HitActor HitComponent HitBone Bone HitItem Element Face TraceStart TraceEnd) (Collision|BreakHitResult Hit))
 (Utilities|Array|Add (Variables|Default|GetPublicShotEnds) (select DidHit ImpactPoint End))
 (Utilities|Array|Add (Variables|Default|GetPublicShotHits) DidHit)
 (if DidHit
  (Variables|Default|SetPublicHasImpact true)
  (Variables|Default|SetPublicImpactLocation ImpactPoint)
  (bind Falloff (select (== (CallFunction|GetActiveFirearmID) "Weapon.Shotgun") (Math|Float|Clamp(Float) (/ (- (Variables|Default|GetShotgunRange) Distance) (- (Variables|Default|GetShotgunRange) (Variables|Default|GetShotgunFullDamageRange))) 0.0 1.0) 1.0))
  (Game|Damage|ApplyPointDamage :DamagedActor HitActor :BaseDamage (* Damage Falloff) :HitFromDirection (Math|Vector|Normalize (- End (Variables|Default|GetShotStart))) :HitInfo Hit :EventInstigator (Pawn|GetController) :DamageCauser self :DamageTypeClass "/Script/Engine.DamageType")))''')
write(bp,'PerformPistolShot','''(fn PerformPistolShot (ViewOrigin ViewDirection)
 (if (Networking|HasAuthority)
  (Variables|Default|SetShotIgnoreActors (Actor|GetAllActorsOfClass :ActorClass "/Game/AIExample/Items/BP_ItemPickup.BP_ItemPickup_C"))
  (Utilities|Array|Add (Variables|Default|GetShotIgnoreActors) self)
  (Variables|Default|SetShotAimPoint (+ ViewOrigin (* (Math|Vector|Normalize ViewDirection) 10000.0)))
  (bind (CameraHit CameraBlocked) (Collision|LineTraceByChannel :Start ViewOrigin :End (Variables|Default|GetShotAimPoint) :TraceChannel "TraceTypeQuery1" :ActorsToIgnore (Variables|Default|GetShotIgnoreActors)))
  (bind (CB CI CT CD CL CameraImpact CN CIN CPM CA CC CHB CBn CItem CE CF CS CEnd) (Collision|BreakHitResult CameraHit))
  (if CameraBlocked (Variables|Default|SetShotAimPoint CameraImpact))
  (Variables|Default|SetShotStart (Transformation|GetSocketLocation :self (CallFunction|GetActiveWeaponVisual) :InSocketName "Muzzle"))
  (Variables|Default|SetShotDirection (Math|Vector|Normalize (- (Variables|Default|GetShotAimPoint) (Variables|Default|GetShotStart))))
  (Variables|Default|SetPublicShotStart (Variables|Default|GetShotStart))
  (Variables|Default|SetPublicShotWeapon (CallFunction|GetActiveFirearmID))
  (Utilities|Array|Clear (Variables|Default|GetPublicShotEnds))
  (Utilities|Array|Clear (Variables|Default|GetPublicShotHits))
  (Variables|Default|SetPublicHasImpact false)
  (if (== (CallFunction|GetActiveFirearmID) "Weapon.Shotgun")
   (bind AimRot (Math|Rotator|MakeRotfromX (Variables|Default|GetShotDirection)))
   (for i (range (Variables|Default|GetShotgunPelletCount))
    (bind Angle (* i (/ 360.0 (Variables|Default|GetShotgunPelletCount))))
    (bind Radius (select (== i 0) 0.0 (* (/ (Variables|Default|GetShotgunSpreadRadiusAt10m) 1000.0) (Variables|Default|GetShotgunRange))))
    (Variables|Default|SetPelletEnd (+ (+ (Variables|Default|GetShotStart) (* (Variables|Default|GetShotDirection) (Variables|Default|GetShotgunRange))) (+ (* (Math|Vector|GetRightVector AimRot) (* Radius (Math|Trig|Cos(Degrees) Angle))) (* (Math|Vector|GetUpVector AimRot) (* Radius (Math|Trig|Sin(Degrees) Angle))))))
    (CallFunction|TraceFirearmPellet :End (Variables|Default|GetPelletEnd) :Damage (Variables|Default|GetShotgunPelletDamage)))
   (else (CallFunction|TraceFirearmPellet :End (+ (Variables|Default|GetShotAimPoint) (* (Variables|Default|GetShotDirection) 2.0)) :Damage (select (== (CallFunction|GetActiveFirearmID) "Weapon.Revolver") (Variables|Default|GetRevolverDamage) 25.0))))
  (Variables|Default|SetPublicShotSerial (+ (Variables|Default|GetPublicShotSerial) 1))))''')
code=code_from('build_shoulder_camera.py','UpdateShoulderCamera').replace('(and (== (Variables|Default|GetPublicActiveSlot) 2) (== (Variables|Default|GetPublicSidearm) "Weapon.Pistol"))',supported('(CallFunction|GetActiveFirearmID)'));write(bp,'UpdateShoulderCamera',code)
code=code_from('build_pistol_character.py','CheckPistolEquip').replace('(and (== (Variables|Default|GetPublicActiveSlot) 2) (== (Variables|Default|GetPublicSidearm) "Weapon.Pistol"))',supported('(CallFunction|GetActiveFirearmID)'))
write(bp,'CheckPistolEquip',code)
B.compile_blueprint(bp,warnings_as_errors=True)
cdo=B.get_default_object(bp)
for n,v in {'ShotgunPelletCount':8,'ShotgunSpreadRadiusAt10m':65.0,'ShotgunPelletDamage':18.0,'ShotgunRange':3000.0,'ShotgunFullDamageRange':700.0,'RevolverDamage':55.0}.items():cdo.set_editor_property(n,v)
save(bp)
